static unsigned checks=0;
static void Check(bool b,const char* why){++checks;if(!b)throw std::runtime_error(why);}
static void Registry(){
    alignas(8) std::array<uint8_t,65536> disk{};threads::Scheduler scheduler;
    const auto block=[](void* raw,io::Op op,uint64_t offset,uint8_t* data)noexcept{auto& bytes=*static_cast<std::array<uint8_t,65536>*>(raw);if(op==io::Op::Flush)return true;if(!data||(offset&511)||offset>bytes.size()-512)return false;if(op==io::Op::Read)std::memcpy(data,bytes.data()+offset,512);else if(op==io::Op::Write)std::memcpy(bytes.data()+offset,data,512);else return false;return true;};
    auto volume=std::make_unique<storage::Volume>();volume->Configure(&disk,block,scheduler);Check(!volume->Mount(),"Registry mount");processes::Token token;token.user=100;token.primaryGroup=10;token.integrity=2;
    const char* paths[]{"HKCU\\Software\\Classes\\CLSID\\{6a140801-1480-4148-8148-000000000001}","HKCU\\Software\\Classes\\CLSID\\{6a140801-1480-4148-8148-000000000002}"};
    for(const auto* path:paths){storage::Command c;c.op=storage::Op::RegCreate;std::strcpy(c.path,path);Check(!volume->Execute(1,token,c),"Long GUID registry creation");c={};c.op=storage::Op::RegSet;std::strcpy(c.path,path);std::strcpy(c.name,"value");c.type=4;c.length=4;c.data[0]=path[std::strlen(path)-2];Check(!volume->Execute(1,token,c),"GUID value independent");}
    for(uint32_t i=0;i<2;++i){storage::Command c;c.op=storage::Op::RegEnum;c.index=i;std::strcpy(c.path,"HKCU\\Software\\Classes\\CLSID");Check(!volume->Execute(1,token,c)&&std::strlen(c.other)==38,"Full GUID enumeration");}
    Check(!volume->Flush()&&!volume->Unmount(),"GUID durable commit");volume->Configure(&disk,block,scheduler);Check(!volume->Mount(),"GUID state remount");
    for(const auto* path:paths){storage::Command c;c.op=storage::Op::RegGet;std::strcpy(c.path,path);std::strcpy(c.name,"value");c.length=512;Check(!volume->Execute(1,token,c)&&c.data[0]==path[std::strlen(path)-2],"GUID state persisted without prefix collision");}
    storage::Command bad;bad.op=storage::Op::RegCreate;std::strcpy(bad.path,"HKCU\\{not-a-valid-long-guid-name-00000000000000000000}");Check(volume->Execute(1,token,bad)==storage::Invalid,"Malformed long key rejected");
    auto image=std::make_unique<storage::Image>();const auto* first=reinterpret_cast<const storage::Image*>(disk.data()+storage::FirstSlot);const auto* second=reinterpret_cast<const storage::Image*>(disk.data()+storage::SecondSlot);*image=first->header.sequence>second->header.sequence?*first:*second;Check(storage::Volume::Validate(*image),"Long-name image canonical");
    for(auto& node:image->nodes)if(node.flags&2){node.data[37]='!';break;}image->header.checksum=storage::Hash(image.get(),sizeof(*image),offsetof(storage::Image,header)+offsetof(storage::Header,checksum),8);Check(!storage::Volume::Validate(*image),"Corrupt long-name payload rejected");Check(!volume->Unmount(),"Registry cleanup");
}
static void Volumes(){for(const auto version:{1u,2u}){const auto header=version==1?uint32_t(sizeof(pevolume::Header)):pevolume::ExtendedBytes;const auto count=version==1?1u:20u;const auto start=(header+4095)&~4095u;std::vector<uint8_t> data(start+count*4096);auto* h=new(data.data())pevolume::Header();h->version=version;h->headerBytes=header;h->bytes=uint32_t(data.size());h->files=count;h->root=count-1;for(uint32_t i=0;i<count;++i){pevolume::File f;std::snprintf(f.path,sizeof(f.path),"c:\\app\\component%u.dll",i);f.offset=start+i*4096;f.bytes=1;f.kind=pevolume::Kind::Pe;data[f.offset]=uint8_t(i+1);f.hash=pevolume::Hash(data.data()+f.offset,1);const auto offset=i<16?48+i*sizeof(f):sizeof(*h)+(i-16)*sizeof(f);std::memcpy(data.data()+offset,&f,sizeof(f));}h->hash=pevolume::Hash(data.data(),uint32_t(data.size()),true);Check(pevolume::Valid(data.data(),uint32_t(data.size())),"Legacy/extended volume accepted");Check(pevolume::FileAt(*h,count-1).bytes==1,"Extended root lookup");auto corrupt=data;corrupt[(version==1?48:sizeof(*h))+128]^=1;reinterpret_cast<pevolume::Header*>(corrupt.data())->hash=pevolume::Hash(corrupt.data(),uint32_t(corrupt.size()),true);Check(!pevolume::Valid(corrupt.data(),uint32_t(corrupt.size())),"Corrupt file extent rejected");h->headerBytes=header-1;h->hash=pevolume::Hash(data.data(),uint32_t(data.size()),true);Check(!pevolume::Valid(data.data(),uint32_t(data.size())),"Header shape rejected");}}
int main(){try{Volumes();Registry();auto memory=std::make_unique<memory::Manager>();auto p=std::make_unique<processes::Manager>();auto scheduler=std::make_unique<threads::Scheduler>();std::vector<uint8_t> ram(16u<<20);const abi::MemoryRegion map[]{{0,0x100000,abi::MemoryKind::Reserved,0,0},{0x100000,ram.size()-0x100000,abi::MemoryKind::Available,0,0}};Check(memory->physical.Initialize(uint64_t(ram.data()),ram.size(),map,2),"Memory");p->Configure(*memory,*scheduler);processes::Token token;token.user=100;token.primaryGroup=10;uint32_t server=0,client=0,foreign=0;Check(!p->CreateRoot(token,server)&&!p->CreateRoot(token,client),"Peers");token.user=200;Check(!p->CreateRoot(token,foreign),"Foreign");const auto st=scheduler->CreateThread(),ct=scheduler->CreateThread(),ft=scheduler->CreateThread();uint64_t handle=0;Check(!p->Attach(server,st,handle)&&!p->Attach(client,ct,handle)&&!p->Attach(foreign,ft,handle),"Ownership");c::Core core;core.Initialize(*p);c::Request reg;reg.op=c::Op::Register;reg.iid[0]=42;Check(!core.Execute(server,st,reg),"Register");const auto endpoint=reg.endpoint;c::Request r;r.op=c::Op::Lookup;r.iid[0]=42;Check(core.Execute(foreign,ft,r)==5,"Cross identity lookup denied");r={};r.op=c::Op::Lookup;r.iid[0]=42;Check(!core.Execute(client,ct,r)&&r.endpoint==endpoint,"Lookup");r={};r.op=c::Op::Call;r.endpoint=endpoint;r.length=3;std::memcpy(r.data,"abc",3);Check(!core.Execute(client,ct,r),"Call");const auto call=r.call;r={};r.op=c::Op::Receive;r.endpoint=endpoint;Check(core.Execute(client,ct,r)==5,"Foreign receive denied");Check(!core.Execute(server,st,r)&&r.call==call&&r.pid==client&&r.length==3&&!std::memcmp(r.data,"abc",3),"Receive exact copy");r.op=c::Op::Reply;r.pid=r.tid=0;r.status=7;r.length=2;r.data[0]='O';r.data[1]='K';Check(core.Execute(client,ct,r)==5,"Spoofed reply denied");Check(!core.Execute(server,st,r),"Reply");r={};r.op=c::Op::Result;r.call=call;Check(core.Execute(foreign,ft,r)==5,"Foreign result denied");Check(!core.Execute(client,ct,r)&&r.status==7&&r.length==2&&r.data[0]=='O',"Result exact copy");r={};r.op=c::Op::Result;r.call=call;Check(core.Execute(client,ct,r)==6,"Result consumed once");uint64_t calls[c::Calls]{};for(auto& id:calls){r={};r.op=c::Op::Call;r.endpoint=endpoint;Check(!core.Execute(client,ct,r),"Call budget fill");id=r.call;}r={};r.op=c::Op::Call;r.endpoint=endpoint;Check(core.Execute(client,ct,r)==1816,"Call quota");r={};r.op=c::Op::Cancel;r.call=calls[0];Check(!core.Execute(client,ct,r),"Cancellation");core.Exit(server,st);for(unsigned i=1;i<c::Calls;++i){r={};r.op=c::Op::Result;r.call=calls[i];Check(!core.Execute(client,ct,r)&&r.status==1726&&!r.length,"Server crash fails pending call");}Check(core.Clean(),"IPC cleanup");r={};r.length=c::Payload+1;Check(core.Execute(client,ct,r)==87,"Oversize rejected");r={};r.version=2;Check(core.Execute(client,ct,r)==87,"Version rejected");r={};Check(core.Execute(server,ct,r)==5,"False thread owner rejected");for(unsigned i=0;i<c::Endpoints;++i){r={};r.op=c::Op::Register;r.iid[0]=uint8_t(i);Check(!core.Execute(server,st,r),"Endpoint budget fill");}r={};r.op=c::Op::Register;r.iid[0]=99;Check(core.Execute(server,st,r)==1816,"Endpoint quota");core.Exit(server);core.Exit(client);core.Exit(foreign);Check(core.Clean(),"All IPC state reclaimed");std::cout<<"Component core "<<checks<<" checks PASS\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
